// openbase.tsx

import { useEffect, useState } from "react";
import { AUTH_ID } from "../config/authid";
import { OBAUTH_BASE_URL } from "../config/openbase-auth-url";

const isBrowser = typeof window !== "undefined";

const getTokenKey = () => {
  const hostname = isBrowser ? window.location.hostname : "server";
  return `__${AUTH_ID}__${hostname}__auth_token`;
};

export const TOKEN_KEY = getTokenKey();





/* ============================================================
   TYPES
   ============================================================ */

type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { [key: string]: JsonValue };

type ApiFetchOptions = Omit<RequestInit, "headers" | "body"> & {
  headers?: HeadersInit;
  body?: JsonValue | string | FormData | URLSearchParams | Blob | ArrayBuffer;
};

/* ============================================================
   INTERNAL TOKEN STORE (memory + persistence)
   ============================================================ */

let _token: string | null = null;

function loadTokenFromStorage() {
  if (_token) return;
  if (!isBrowser) return;

  const stored = window.localStorage.getItem(getTokenKey());
  if (stored) {
    _token = stored;
  }
}

export const setToken = (t: string | null) => {
  _token = t;
  if (!isBrowser) return;

  if (t) {
    window.localStorage.setItem(getTokenKey(), t);
  } else {
    window.localStorage.removeItem(getTokenKey());
  }
};

export const getToken = () => {
  loadTokenFromStorage();
  return _token;
};

export const clearToken = () => {
  _token = null;
  if (isBrowser) {
    window.localStorage.removeItem(getTokenKey());
  }
};

/* ============================================================
   HELPERS
   ============================================================ */

function buildHeaders(input?: HeadersInit, includeJson = true): Headers {
  loadTokenFromStorage();

  const headers = new Headers(input);

  if (includeJson && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }

  if (_token && !headers.has("Authorization")) {
    headers.set("Authorization", `Bearer ${_token}`);
  }

  return headers;
}

function isRawBody(body: ApiFetchOptions["body"]) {
  return (
    typeof body === "string" ||
    (typeof FormData !== "undefined" && body instanceof FormData) ||
    (typeof URLSearchParams !== "undefined" && body instanceof URLSearchParams) ||
    (typeof Blob !== "undefined" && body instanceof Blob) ||
    (typeof ArrayBuffer !== "undefined" && body instanceof ArrayBuffer)
  );
}

/* ============================================================
   CORE FETCH WRAPPER
   ============================================================ */

async function apiFetch(path: string, options: ApiFetchOptions = {}) {
  const body = options.body;
  const requestBody: BodyInit | undefined =
    body === undefined
      ? undefined
      : isRawBody(body)
      ? body
      : JSON.stringify(body);

  const headers = buildHeaders(
    options.headers,
    !(typeof FormData !== "undefined" && body instanceof FormData)
  );

  const res = await fetch(`${OBAUTH_BASE_URL}${path}`, {
    ...options,
    headers,
    body: requestBody,
  });

  const text = await res.text();

  let data: any;
  try {
    data = JSON.parse(text);
  } catch {
    data = text;
  }

  if (!res.ok) {
    throw {
      status: res.status,
      data,
    };
  }

  return data;
}

/* ============================================================
   AUTH FUNCTIONS
   ============================================================ */

export async function login(email: string, password: string) {
  const data = await apiFetch("/auth/login", {
    method: "POST",
    body: { email, password },
  });

  if (data?.token) {
    setToken(data.token);
  }

  return data;
}

export function logout() {
  clearToken();
}

export async function getMe() {
  return apiFetch("/auth/me", {
    method: "GET",
  });
}

/* ============================================================
   SIGNUP FLOW
   ============================================================ */

export async function signup(email: string, password: string) {
  return apiFetch("/auth/action", {
    method: "POST",
    body: {
      action: "signup",
      email,
      password,
    },
  });
}

/* ============================================================
   PASSWORD RESET FLOW
   ============================================================ */

export async function requestPasswordReset(email: string) {
  return apiFetch("/auth/action", {
    method: "POST",
    body: {
      action: "request_password_reset",
      email,
    },
  });
}

export async function resetPassword(token: string, password: string) {
  return apiFetch("/auth/action", {
    method: "POST",
    body: {
      action: "reset_password",
      token,
      password,
    },
  });
}

/* ============================================================
   GENERIC AUTH-AWARE REQUEST
   ============================================================ */

export async function authedRequest(
  path: string,
  method: string = "GET",
  body?: JsonValue | string | FormData | URLSearchParams | Blob | ArrayBuffer,
  headers?: HeadersInit
) {
  return apiFetch(path, {
    method,
    headers,
    body,
  });
}

/* ============================================================
   OPTIONAL HELPERS
   ============================================================ */

export async function isLoggedIn(): Promise<boolean> {
  try {
    await getMe();
    return true;
  } catch {
    return false;
  }
}

export async function initAuth() {
  loadTokenFromStorage();

  if (!_token) return false;

  try {
    await getMe();
    return true;
  } catch {
    clearToken();
    return false;
  }
}


export function useOpenbase() {
  const [loading, setLoading] = useState(true);
  const [openbase, setOpenbase] = useState(false);

  useEffect(() => {
    let mounted = true;

    const run = async () => {
      try {
        const ok = await initAuth();
        if (mounted) setOpenbase(ok);
      } catch {
        if (mounted) setOpenbase(false);
      } finally {
        if (mounted) setLoading(false);
      }
    };

    run();

    return () => {
      mounted = false;
    };
  }, []);

  return { loading, openbase };
}
